import { useState, useCallback, useEffect } from 'react';
import { useUiStore } from '../stores/useUiStore';
import { getViewMeta } from '../core/view-meta';

/**
 * componentName() — derive a React component name from a source path.
 *
 * `src/pages/SymbolPage.jsx`      -> `SymbolPage`
 * `src/pages/ViewStrategyPage.jsx` -> `ViewStrategyPage`
 *
 * Returns `'unknown'` when there is no usable path, so the copied prompt says "unknown" rather
 * than inventing a name. Used by the Copy View Info block above — see the comment there for why
 * this is derived from `meta.file` instead of `meta.label`.
 */
function componentName(file) {
  if (!file) return 'unknown';
  const base = file.split('/').pop() || '';
  return base.replace(/\.(jsx|js|tsx|ts)$/i, '') || 'unknown';
}

/**
 * Dev Overlay — primary panel for Admin + Status information.
 *
 * Always shows when devOverlayOpen is true. Admin/Status data is the
 * primary content; tagged runtime elements appear below.
 *
 * Inspect Mode: click any UI element to open its source file in VS Code.
 * Requires `code` command in PATH on the development machine.
 */
export default function DevOverlay({
  healthQuery,
  availableAdapters,
  analyticsSnapshot,
  performanceSnapshot,
  onDownloadRuntimeReport,
}) {
  const open = useUiStore((state) => state.devOverlayOpen);
  const [inspectMode, setInspectMode] = useState(false);
  const [inspectAction, setInspectAction] = useState('open'); // 'open' | 'copy'
  const [copiedMsg, setCopiedMsg] = useState('');

  // ── Copy View Info ──
  const handleCopyViewInfo = useCallback(() => {
    const pathname = window.location.pathname;
    const meta = getViewMeta(pathname);
    if (!meta) {
      // Generate a prompt for AI to register this view's metadata
      const text = [
        `View:       (No metadata registered for this route)`,
        `Route:      ${window.location.pathname}`,
        `URL:        ${window.location.origin}${window.location.pathname}`,
        ``,
        `This view needs metadata. Please:`,
        `1. Add an entry to src/core/view-meta.js mapping this route`,
        `2. Ensure the view ID is registered in src/core/view-routes.jsx`,
        `3. Add a nav entry in src/core/nav-tree.js under the correct area`,
      ].join('\n');
      navigator.clipboard.writeText(text).then(() => {
        setCopiedMsg('Prompt copied — paste to AI to register metadata');
        setTimeout(() => setCopiedMsg(''), 3000);
      }).catch(() => {
        setCopiedMsg('Copy failed');
        setTimeout(() => setCopiedMsg(''), 2000);
      });
      return;
    }
    const text = [
      `View:       ${meta.label}`,
      `Route:      ${window.location.pathname}`,
      `File:       ${meta.file}`,
      `CSS:        ${meta.css}`,
      `API:        ${(meta.api || []).join(', ') || 'None'}`,
      // ⚠️ Derived from `meta.file`, NOT from `meta.label`. The previous version was
      // `meta.label.replace(/\s+/g, '')`, which INVENTED a component name: the entry at
      // `/research/symbol` is labelled "Symbol Detail" and renders `SymbolPage`, so the copied
      // prompt claimed `<SymbolDetail />` — a component that does not exist. A plausible wrong
      // answer is worse than no answer, and this block is pasted into an AI prompt as fact.
      // Deriving from the real file path cannot drift from what actually renders.
      `Component:  <${componentName(meta.file)} />`,
    ].join('\n');
    navigator.clipboard.writeText(text).then(() => {
      setCopiedMsg('View info copied!');
      setTimeout(() => setCopiedMsg(''), 2000);
    }).catch(() => {
      setCopiedMsg('Copy failed');
      setTimeout(() => setCopiedMsg(''), 2000);
    });
  }, []);

  // ── Open View File ──
  const handleOpenViewFile = useCallback(() => {
    const meta = getViewMeta(window.location.pathname);
    if (!meta?.file) {
      setCopiedMsg('No source file mapped for this route');
      setTimeout(() => setCopiedMsg(''), 2000);
      return;
    }
    setCopiedMsg(`Opening ${meta.file}...`);
    fetch('http://localhost:3201/api/dev/open-file', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ file: meta.file }),
    }).then(r => r.json()).then(data => {
      setCopiedMsg(data.opened ? `Opened: ${meta.file}` : `Failed: ${data.error || 'unknown'}`);
      setTimeout(() => setCopiedMsg(''), 3000);
    }).catch(() => {
      setCopiedMsg('Backend unreachable');
      setTimeout(() => setCopiedMsg(''), 2000);
    });
  }, []);

  // ── Element Inspector Mode ──
  useEffect(() => {
    if (!inspectMode) return;

    let hoveredEl = null;
    // Source-mappable elements. Headings map to source lines best, but interactive
    // controls (buttons, links, toggles) are also selectable so their handler/label
    // can be located in the file.
    const MAPPABLE = new Set(['H1','H2','H3','H4','H5','H6','TH','LABEL','LEGEND','BUTTON','A','SUMMARY','DT','OPTION']);

    function onMouseMove(e) {
      if (hoveredEl) {
        hoveredEl.style.outline = '';
        hoveredEl = null;
      }
      let el = document.elementFromPoint(e.clientX, e.clientY);
      if (!el || el === document.body || el === document.documentElement) return;

      // In 'open' mode, only target mappable elements — climb to the nearest
      // mappable ancestor so a button's nested text still resolves to the button.
      if (inspectAction === 'open') {
        let cur = el;
        while (cur && cur !== document.body) {
          if (MAPPABLE.has(cur.tagName)) { el = cur; break; }
          cur = cur.parentElement;
        }
        if (!cur || cur === document.body) return;
      }

      hoveredEl = el;
      el.style.outline = '2px solid #f59e0b';
      el.style.outlineOffset = '1px';
    }

    function onClick(e) {
      if (!hoveredEl) return;
      e.preventDefault();
      e.stopPropagation();
      
      const meta = getViewMeta(window.location.pathname);
      const file = meta?.file || null;
      const text = (hoveredEl.textContent || '').trim().replace(/\s+/g, ' ').substring(0, 60);

      if (inspectAction === 'open' && file) {
        // Open file at matching line
        setCopiedMsg(text ? `Opening "${text}"...` : `Opening ${file}...`);
        fetch('http://localhost:3201/api/dev/open-file', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ file, query: text || undefined }),
        }).then(r => r.json()).then(data => {
          setCopiedMsg(data.line ? `Opened ${file}:${data.line}` : data.opened ? `Opened: ${file}` : `Failed`);
          setTimeout(() => setCopiedMsg(''), 3000);
        }).catch(() => { setCopiedMsg('Backend unreachable'); setTimeout(() => setCopiedMsg(''), 2000); });
      } else {
        // Copy element info only
        const tag = hoveredEl.tagName.toLowerCase();
        const id = hoveredEl.id ? `#${hoveredEl.id}` : '';
        const cls = hoveredEl.className && typeof hoveredEl.className === 'string'
          ? `.${hoveredEl.className.split(' ').filter(Boolean).join('.')}` : '';
        const info = `Element:  <${tag}${id}${cls}>\nText:     ${text || '(none)'}\nSource:   ${window.location.pathname}`;
        navigator.clipboard.writeText(info).then(() => {
          setCopiedMsg('Element copied!');
          setTimeout(() => setCopiedMsg(''), 2000);
        }).catch(() => {});
      }

      if (hoveredEl) { hoveredEl.style.outline = ''; hoveredEl = null; }
      setInspectMode(false);
    }

    document.addEventListener('mousemove', onMouseMove, true);
    document.addEventListener('click', onClick, true);
    document.body.style.cursor = 'crosshair';

    return () => {
      document.removeEventListener('mousemove', onMouseMove, true);
      document.removeEventListener('click', onClick, true);
      document.body.style.cursor = '';
      if (hoveredEl) hoveredEl.style.outline = '';
    };
  }, [inspectMode, inspectAction]);

  // ── Escape key closes inspect mode or overlay ──
  const toggleDevOverlay = useUiStore((state) => state.toggleDevOverlay);
  useEffect(() => {
    if (!open) return;
    function onKey(e) {
      if (e.key === 'Escape') {
        if (inspectMode) {
          setInspectMode(false);
        } else {
          toggleDevOverlay();
        }
      }
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, inspectMode, toggleDevOverlay]);

  if (!open) return null;

  const healthData = healthQuery?.data || null;
  const healthLoading = healthQuery?.isLoading || false;
  const healthError = healthQuery?.error || null;

  return (
    <div className="dev-overlay-content">
      {/* ── System Status ── */}
      <section className="dev-admin-section">
        <h3 className="dev-section-title">System</h3>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Server</span>
          <span className={`dev-stat-value ${healthData ? 'ok' : healthError ? 'error' : 'muted'}`}>
            {healthLoading ? '…' : healthData ? 'Online' : healthError ? 'Offline' : '—'}
          </span>
        </div>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Version</span>
          <span className="dev-stat-value muted">{healthData?.version || '—'}</span>
        </div>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Adapters</span>
          <span className="dev-stat-value">{availableAdapters.length}</span>
        </div>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Analytics</span>
          <span className="dev-stat-value muted">{analyticsSnapshot.queueLength} queued</span>
        </div>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Perf</span>
          <span className="dev-stat-value muted">{performanceSnapshot.samples} samples</span>
        </div>

        <div className="dev-stat-row">
          <span className="dev-stat-label">Vitals</span>
          <span className="dev-stat-value muted">{performanceSnapshot.started ? 'Active' : 'Idle'}</span>
        </div>
      </section>

        {/* Actions */}
        <div className="dev-actions">
          <button
            type="button"
            onClick={onDownloadRuntimeReport}
            className="dev-action-btn"
          >
            Export Report
          </button>
          <button
            type="button"
            onClick={handleCopyViewInfo}
            className="dev-action-btn"
            style={{ marginTop: '0.35rem' }}
          >
            📋 Copy View Info
          </button>
          <button
            type="button"
            onClick={handleOpenViewFile}
            className="dev-action-btn"
            style={{ marginTop: '0.35rem' }}
          >
            📂 Open View File
          </button>
          <button
            type="button"
            onClick={() => { setInspectAction('open'); setInspectMode(true); setCopiedMsg(''); }}
            className="dev-action-btn"
            style={{ marginTop: '0.35rem' }}
          >
            {inspectMode && inspectAction === 'open' ? '🔍 Click a heading or control to jump to its line...' : '🔍 Inspect & Open'}
          </button>
          <button
            type="button"
            onClick={() => { setInspectAction('copy'); setInspectMode(true); setCopiedMsg(''); }}
            className="dev-action-btn"
            style={{ marginTop: '0.35rem' }}
          >
            {inspectMode && inspectAction === 'copy' ? '🔎 Click element to copy info...' : '🔎 Inspect & Copy'}
          </button>
          {copiedMsg && (
            <span style={{ fontSize: '0.68rem', color: '#22c55e', display: 'block', marginTop: '0.25rem' }}>
              {copiedMsg}
            </span>
          )}
        </div>
    </div>
  );
}
